## PROBE — full source, `<mat>\tracked-object-probe.mjs`
```js
import { pathToFileURL } from "node:url";
const base = pathToFileURL(process.cwd() + "/apps/daemon/src/projects/").href;

// The three .js BRIDGES, by file URL — not the .ts sources.
const files  = await import(base + "project-manager-files.js");
const launch = await import(base + "project-manager-launch.js");
const env    = await import(base + "project-launch-environment.js");

// Rosters come from the BARE specifier and are used ONLY to build the input.
// The daemon modules do not re-export them, so asserting .length on a daemon
// namespace would be unevaluable on committed bytes.
const runner  = await import("@moe/runner");
const envKeys  = [...runner.PROJECT_STACK_ENVIRONMENT_KEYS];
const credKeys = [...runner.PROJECT_STACK_PROVIDER_CREDENTIAL_KEYS];

const out = [];
const check = (name, actual, expected) => {
  const ok = actual === expected;
  out.push(`${ok ? "PASS" : "FAIL"}  ${name}: ${JSON.stringify(actual)}` +
           (ok ? "" : ` (expected ${JSON.stringify(expected)})`));
  return ok;
};

let ok = true;
ok = check("PROJECT_MANAGER_FILES_LAYER",  files.PROJECT_MANAGER_FILES_LAYER,  "PROJECT_MANAGER_FILES")  && ok;
ok = check("PROJECT_MANAGER_LAUNCH_LAYER", launch.PROJECT_MANAGER_LAUNCH_LAYER,"PROJECT_MANAGER_LAUNCH") && ok;
ok = check("typeof snapshotProjectLaunchEnvironment", typeof env.snapshotProjectLaunchEnvironment, "function") && ok;
ok = check("typeof selectedProviderEnvironment",      typeof env.selectedProviderEnvironment,      "function") && ok;

const DECOYS = ["NOT_A_STACK_KEY", "not_a_stack_key_2"];
const input = {};
for (const k of envKeys) input[k] = `v-${k}`;
for (const d of DECOYS)  input[d] = "decoy";

const snapshot   = env.snapshotProjectLaunchEnvironment(input);
const kept       = Object.keys(snapshot);
const decoysGone = DECOYS.every((d) => !(d in snapshot));
ok = check("input key count",   Object.keys(input).length, envKeys.length + DECOYS.length) && ok;
ok = check("snapshot kept",     kept.length,               envKeys.length)                 && ok;
ok = check("decoys filtered",   decoysGone,                true)                           && ok;

const stripped = env.selectedProviderEnvironment(snapshot, {});
ok = check("after credential strip", Object.keys(stripped).length, envKeys.length - credKeys.length) && ok;

out.push(`ROSTERS: environment=${envKeys.length} credentials=${credKeys.length}`);
out.push(`SUMMARY: input ${Object.keys(input).length} | snapshot kept ${kept.length} | ` +
         `decoys filtered ${decoysGone} | after credential strip ${Object.keys(stripped).length}`);
console.log(out.join("\n"));
process.exit(ok ? 0 : 1);
```
Note the expectations are DERIVED from the rosters (`envKeys.length`, `envKeys.length - credKeys.length`), not hard-coded to 43/36. A hard-coded pair would go silently stale if the roster changed; this way a roster change reds the arm that reports the roster size rather than the arm that reports the behaviour.

